    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetTombstone() => int.MinValue; // todo: @improve separate the tombstone from the hash

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(int x, int y) => x == y;

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(int key) => key;
}

/// <summary>General tools for IEq and its implementations</summary>
public static class Eq
{
    /// <summary>Factor to multiple by, to achieve the Fibonacci hashing (2^32 / phi, where phi is the golden ratio ~1.61803).</summary>
    public const uint GoldenRatioFactor32 = 2654435769;
}

/// <summary>Instances of the RefEq for the often used K</summary>
public static class RefEq
{
    /// <summary>RefEq for object, possibly the only thing you need</summary>
    public static readonly RefEq<object> OfObject = default;
}

/// <summary>Uses the `RuntimeHelpers.GetHashCode` and `object.ReferenceEquals`</summary>
public struct RefEq<K> : IEq<K> where K : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public K GetTombstone() => null;

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(K x, K y) => ReferenceEquals(x, y);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(K key) => RuntimeHelpers.GetHashCode(key);
}

/// <summary>Uses the `RuntimeHelpers.GetHashCode` and hashes the result with Fibonacci hashing via * GoldenRatio</summary>
public struct GoldenRatioRefEq<K> : IEq<K> where K : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public K GetTombstone() => null;

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals(K x, K y) => ReferenceEquals(x, y);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(K key) => (int)(RuntimeHelpers.GetHashCode(key) * Eq.GoldenRatioFactor32);
}

/// <summary>Compares via `ReferenceEquals` and gets the hash faster via `RuntimeHelpers.GetHashCode`</summary>
public struct RefEq<A, B> : IEq<(A, B)>
    where A : class
    where B : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public (A, B) GetTombstone() => (null, null);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals((A, B) x, (A, B) y) =>
        ReferenceEquals(x.Item1, y.Item1) && ReferenceEquals(x.Item2, y.Item2);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode((A, B) key) =>
        Hasher.Combine(RuntimeHelpers.GetHashCode(key.Item1), RuntimeHelpers.GetHashCode(key.Item2));
}

/// <summary>Compares via `ReferenceEquals` and gets the hash faster via `RuntimeHelpers.GetHashCode`</summary>
public struct RefEq<A, B, C> : IEq<(A, B, C)>
    where A : class
    where B : class
    where C : class
{
    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public (A, B, C) GetTombstone() => (null, null, null);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public bool Equals((A, B, C) x, (A, B, C) y) =>
        ReferenceEquals(x.Item1, y.Item1) && ReferenceEquals(x.Item2, y.Item2) && ReferenceEquals(x.Item3, y.Item3);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode((A, B, C) key) =>
        Hasher.Combine(RuntimeHelpers.GetHashCode(key.Item1), Hasher.Combine(RuntimeHelpers.GetHashCode(key.Item2), RuntimeHelpers.GetHashCode(key.Item3)));
}

/// <summary>Add the Use parameter to `Method{T}(..., Use{T} _)` to enable type inference for T,
/// by calling it as `var t = Method(..., Use{T}.It)`</summary>
public readonly struct Pass<A>
{
    public static readonly Pass<A> It = new();
    public readonly A Aval;
}

/// <summary>Add the Pass parameter in type inference for A, B</summary>
public readonly struct Pass<A, B>
{
    public static readonly Pass<A, B> It = new();
    public readonly A Aval;
    public readonly B Bval;
}

/// <summary>Add the Pass parameter in type inference for A, B, C</summary>
public readonly struct Pass<A, B, C>
{
    public static readonly Pass<A, B, C> It = new();
    public readonly A Aval;
    public readonly B Bval;
    public readonly C Cval;
}

/// <summary>Configuration and the tools for the SmallMap and friends</summary>
public static class SmallMap
{
    internal const uint MinCapacity = 16;
    internal const byte MinFreeCapacityShift = 3; // e.g. for the capacity 16: 16 >> 3 => 2, 12.5% of the free hash slots (it does not mean the entries free slot)
    internal const int EntryIndexStartAtBit = 32; // higher bits for the entry index
    internal const long HashAndProbeMask = (1L << EntryIndexStartAtBit) - 1; // lower 32 bits

    /// <summary>Represent a keyed entry stored in the SmallMap.
    /// Its implementation struct may include the additional Value for the Map or just the Key for the Set.
    /// The implementation may also decide to make Value readonly or writable for the in-place update</summary>
    public interface IEntry<K>
    {
        /// <summary>Returns the key of the payload</summary>
        K Key { get; set; }
    }

    /// <summary>The entry with just a key.
    /// When used in the SmallMap it may represent a Set without wasting the space for the absent value</summary>
    [DebuggerDisplay("{Key?.ToString()}")]
    public struct Entry<K> : IEntry<K>
    {
        /// <summary>The readonly key</summary>
        public K Key { get; set; }
        /// <summary>Construct with the key and default value</summary>
        public Entry(K key) => Key = key;
    }

    /// <summary>Holds an entry consisting of key and value.</summary>
    [DebuggerDisplay("{Key?.ToString()}:{Value}")]
    public struct Entry<K, V> : IEntry<K>
    {
        /// <summary>The readonly key</summary>
        public K Key { get; set; }
        /// <summary>The mutable value</summary>
        public V Value;
        /// <summary>Construct with the key and default value</summary>
        public Entry(K key) => Key = key;
        /// <summary>Construct with the key and value</summary>
        public Entry(K key, V value)
        {
            Key = key;
            Value = value;
        }
    }

    /// <summary>Gets the next power of two greater than or equal to the specified capacity.</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static uint GetNextPowerOfTwoFast(uint capacity)
    {
#if NET8_0_OR_GREATER
        return BitOperations.RoundUpToPowerOf2(capacity);
#else
        --capacity;
        capacity |= capacity >> 1;
        capacity |= capacity >> 2;
        capacity |= capacity >> 4;
        capacity |= capacity >> 8;
        capacity |= capacity >> 16;
        return capacity + 1;
#endif
    }

    /// <summary>Abstraction to configure your own entries data structure. Check the derived types for the examples</summary>
    public interface IEntries<K, TEntry>
        where TEntry : struct, IEntry<K>
    {
        public int Capacity { get; }

        /// <summary>Tracks the number of store elements, enables method AddDefaultAndGetRef to work</summary>
        public int Count { get; }

        /// <summary>Initializes the entries storage to the specified capacity</summary>
        void Init(uint capacity);

        /// <summary>Returns the reference to entry by its index, index should map to the present/non-removed entry</summary>
        ref TEntry GetSurePresentRef(int index);

        /// <summary>Adds the key at the "end" of entries - so the order of addition is preserved.</summary>
        ref TEntry AddDefaultAndGetRef();
    }

    /// <summary>Stores the entries in a single dynamically reallocated growing array</summary>
    public struct SingleArrayEntries<K, TEntry> : IEntries<K, TEntry>
        where TEntry : struct, IEntry<K>
    {
        internal TEntry[] _entries;
        internal int _capacityPowerOfTwo;
        internal int _count;

        /// <inheritdoc/>
        public int Capacity => _capacityPowerOfTwo;
        /// <inheritdoc/>
        public int Count => _count;

        /// <inheritdoc/>
        public void Init(uint capacity)
        {
            _capacityPowerOfTwo = (int)GetNextPowerOfTwoFast(capacity);
            _entries = new TEntry[_capacityPowerOfTwo];
        }

        /// <inheritdoc/>
        [MethodImpl((MethodImplOptions)256)]
        public ref TEntry GetSurePresentRef(int index)
        {
            Debug.Assert(index >= 0 && index < _count, $"Index {index} should be in the range 0..{_count - 1}");
            return ref _entries.GetSurePresentItemRef(index);
        }

        /// <inheritdoc/>
        [MethodImpl((MethodImplOptions)256)]
        public ref TEntry AddDefaultAndGetRef()
        {
            Debug.Assert(_count <= _entries.Length, "Entries should be initialized before adding the item");
            if (_count == _entries.Length)
            {
                Debug.Assert(_capacityPowerOfTwo == _entries.Length, "Capacity should be equal to the entries length");
                _capacityPowerOfTwo <<= 1;
                Array.Resize(ref _entries, _capacityPowerOfTwo);
            }
            return ref _entries.GetSurePresentItemRef(_count++);
        }
    }

    /// <summary>Stores the data in the growing list of bucket arrays.
    /// Allocating the new bucket doubles the size preserving the previous buckets intact ensuring that the item references remain stable,
    /// e.g. the bucket sizes are [32, 32, 64, 128, 256, 512, 1024, ...]</summary>
    [StructLayout(LayoutKind.Sequential, Pack = 1)]
    public struct StableArrayEntries<K, TEntry> : IEntries<K, TEntry>
        where TEntry : struct, IEntry<K>
    {
        internal TEntry[] _bucket00Of32;
        internal TEntry[] _bucket01Of32;
        internal TEntry[] _bucket02Of64;
        internal TEntry[] _bucket03Of128;
        internal TEntry[] _bucket04Of256;
        internal TEntry[] _bucket05Of512;
        internal TEntry[] _bucket06Of1024;
        internal TEntry[] _bucket07Of2048;
        internal TEntry[][] _bucketsOf4096AndMore;

        internal int _capacityPowerOfTwo;
        internal int _count;

        /// <inheritdoc/>
        public int Capacity => _capacityPowerOfTwo;
        /// <inheritdoc/>
        public int Count => _count;

#if NET6_0_OR_GREATER
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        // Starting from the 0 bucket of 32 items: 0b00000000_00000000_00000000_00011111 = 31
        private static int GetBucketIndexFromGlobalIndex(uint index)
        {
            var bucketIndex = 27 - BitOperations.LeadingZeroCount(index);
            // For index < 32: LeadingZeroCount gives 27-32, so 27-lzc gives -5 to 0
            // We want to set (clamp) negative values to 0, [-5..-1] => 0
            // Arithmetic right shift (bucketIndex >> 31) will convert any negative to -1 (0xFFFFFFFF), and 0 or positive to 0
            // Then inverting ~(-1) will give 0 mask to erase any negative bucketIndex to 0. 
            // Inverting ~(0) will give -1 mask to keep any positive bucketIndex as is.
            return bucketIndex & ~(bucketIndex >> 31);
        }
#else
        private static int GetBucketIndexFromGlobalIndex(uint index)
        {
            if (index < 32) return 0;

            var count = 0;
            if (index <= 0x0000FFFF) { count += 16; index <<= 16; }
            if (index <= 0x00FFFFFF) { count += 8;  index <<= 8; }
            if (index <= 0x0FFFFFFF) { count += 4;  index <<= 4; }
            if (index <= 0x3FFFFFFF) { count += 2;  index <<= 2; }
            if (index <= 0x7FFFFFFF) { count += 1; }

            return 27 - count;
        }
#endif

        /// <inheritdoc/>
        [UnscopedRef]
        [MethodImpl((MethodImplOptions)256)]
        private ref TEntry[] GetStackBucketRef(int bucketIndex)
        {
            Debug.Assert(bucketIndex >= 0 && bucketIndex < 8, "Bucket index should be in the range 0..7");
#if SUPPORTS_UNSAFE
            return ref Unsafe.Add(ref _bucket00Of32, bucketIndex);
#else
            switch (bucketIndex)
            {
                case 0: return ref _bucket00Of32;
                case 1: return ref _bucket01Of32;
                case 2: return ref _bucket02Of64;
                case 3: return ref _bucket03Of128;
                case 4: return ref _bucket04Of256;
                case 5: return ref _bucket05Of512;
                case 6: return ref _bucket06Of1024;
                default: return ref _bucket07Of2048;
            }
#endif
        }

        /// <summary>Initializes enough buckets to hold the specified capacity.
        /// Always creates at least the first bucket of 32 items.</summary>
        public void Init(uint capacity = 1)
        {
            _bucket00Of32 = new TEntry[32];
            _capacityPowerOfTwo = 32;
            if (capacity <= 32)
                return;

            var lastBucketIndex = GetBucketIndexFromGlobalIndex(capacity - 1);
            for (var i = 1; i <= lastBucketIndex; i++)
                GetStackBucketRef(i) = new TEntry[32 << (i - 1)];
            _capacityPowerOfTwo = 32 << lastBucketIndex;
            if (lastBucketIndex < 8)
                return;

            _bucketsOf4096AndMore = new TEntry[lastBucketIndex - 7][];
            for (var i = 0; i < _bucketsOf4096AndMore.Length; i++)
                _bucketsOf4096AndMore[i] = new TEntry[4096 << i];
        }

        /// <inheritdoc/>
        [MethodImpl((MethodImplOptions)256)]
        public ref TEntry GetSurePresentRef(int index)
        {
            Debug.Assert(index >= 0 && index < _count, $"Index {index} should be in the range 0..{_count - 1}");
            if (index < 32)
                return ref _bucket00Of32.GetSurePresentItemRef(index);

            var bucketIndex = GetBucketIndexFromGlobalIndex((uint)index); Debug.Assert(bucketIndex > 0, $"Bucket index should be more than 0 here but found {bucketIndex}");
            var insideIndex = index - (32 << (bucketIndex - 1));
            var bucket = bucketIndex < 8 ? GetStackBucketRef(bucketIndex) : _bucketsOf4096AndMore[bucketIndex - 8];
            return ref bucket.GetSurePresentItemRef(insideIndex);
        }

        /// <inheritdoc/>
        [MethodImpl((MethodImplOptions)256)]
        public ref TEntry AddDefaultAndGetRef()
        {
            var lastIndex = _count++;
            if (lastIndex < 32)
            {
                _capacityPowerOfTwo = 32;
                if (_bucket00Of32 == null)
                    _bucket00Of32 = new TEntry[32];
                return ref _bucket00Of32.GetSurePresentItemRef(lastIndex);
            }

            var bucketIndex = GetBucketIndexFromGlobalIndex((uint)lastIndex);
            var fullBacketsCapacity = 32 << (bucketIndex - 1);
            _capacityPowerOfTwo = fullBacketsCapacity << 1;
            if (bucketIndex < 8)
            {
                ref var bucket = ref GetStackBucketRef(bucketIndex);
                if (bucket == null)
                    bucket = new TEntry[fullBacketsCapacity];
                return ref bucket.GetSurePresentItemRef(lastIndex - fullBacketsCapacity);
            }
            else
            {
                var heapBucketCount = bucketIndex - 7;
                if (_bucketsOf4096AndMore == null)
                    _bucketsOf4096AndMore = new TEntry[heapBucketCount][];
                else if (_bucketsOf4096AndMore.Length < heapBucketCount)
                    Array.Resize(ref _bucketsOf4096AndMore, heapBucketCount);

                ref var bucket = ref _bucketsOf4096AndMore[heapBucketCount - 1];
                if (bucket == null)
                    bucket = new TEntry[fullBacketsCapacity];
                return ref bucket.GetSurePresentItemRef(lastIndex - fullBacketsCapacity);
            }
        }
    }

    /// <summary>Lookup for the K in the TStackEntries, first by calculating it hash with TEq and searching the hash in the TStackHashes</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static int TryGetStackEntryIndex<K, TEntry, TEq, TCap, TStackHashes, TStackEntries>(
        this ref TStackEntries entries, ref TStackHashes hashes, int count, K key, int hash,
        Pass<TEq, TCap, TEntry> it = default)
        where TEntry : struct, IEntry<K>
        where TEq : struct, IEq<K>
        where TStackHashes : struct, IStack<int, TCap, TStackHashes>
        where TStackEntries : struct, IStack<TEntry, TCap, TStackEntries>
        where TCap : struct, ISize2Plus
    {
        var cap = default(TCap).Size;
        Debug.Assert(count <= cap, $"SmallMap.TryGetStackEntryIndex: count {count} should be <= stack capacity {cap}");

#if NET8_0_OR_GREATER
        if (cap >= 8 & Vector256.IsHardwareAccelerated)
        {
            if (count == 0)
                return -1;

            var vHash = Vector256.Create(hash);
            var vHashes = MemoryMarshal.Cast<int, Vector256<int>>(hashes.AsSpan());
            var i = 0;
            foreach (var vCurr in vHashes)
            {
                var vMatches = Vector256.Equals(vCurr, vHash);
                var matches = Vector256.ExtractMostSignificantBits(vMatches);
                while (matches != 0)
                {
                    var matchIndex = BitOperations.TrailingZeroCount(matches) + i;
                    if (matchIndex >= count) // todo: @perf can I remove this branch?
                        return -1;

                    if (default(TEq).Equals(entries.GetSurePresentItemRef(matchIndex).Key, key))
                        return matchIndex;

                    // Clear lower bits up to and including the first set bit, afaik it can be hw accelerated 
                    // 0b0001_1000 & (0b0001_1000 - 1) -> & 0b0001_1000 & 0b0001_0111 -> 0b0001_0000 
                    matches &= matches - 1;
                }
                if ((i += Vector256<int>.Count) >= count) // todo: @perf can I remove this branch, what if the hash would be not null?
                    return -1;
            }
            return -1;
        }
#endif
        for (var i = 0; i < count; ++i)
        {
            var h = hashes.GetSurePresentItemRef(i);
            if (hashes.GetSurePresentItemRef(i) == hash &&
                default(TEq).Equals(entries.GetSurePresentItemRef(i).Key, key))
                return i;
        }
        return -1;
    }

    /// <summary>Adds or updates the entry with the provided value.
    /// Returns `true` if it is updated the existing value.</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static bool AddOrUpdate<TMap, K, V>(this ref TMap map, K key, in V value)
        where TMap : struct, IMap<K, Entry<K, V>>
    {
        map.AddOrGetEntryRef(key, out var found).Value = value;
        return found;
    }

    /// <summary>Lookups for the stored entry by key. Returns the found value or provided default</summary>
    [MethodImpl((MethodImplOptions)256)]
    public static V GetValueOrDefault<TMap, K, V>(this ref TMap map, K key, V defaultValue = default)
        where TMap : struct, IMap<K, Entry<K, V>>
    {
        ref var e = ref map.TryGetEntryRef(key, out var found);
        if (found) return e.Value;
        return defaultValue;
    }
}

/// <summary>Methods to verify the integrity and invariants of SmallMap</summary>
public static class SmallMapDiagnostics
{
    /// <summary>Verifies the integrity and invariants of the SmallMap</summary>
    public static void Verify<TMap, K>(ref this TMap map,
        Action<bool, string> assertCond, IEnumerable<K> expectedKeys = null, Pass<K> pass = default)
        where TMap : struct, IMap<K>, IMapImpl<K>
    {
        map.VerifyHashesAndKeysEq(assertCond, pass);

        map.VerifyProbesRobinHoodInvariants(assertCond, pass);

        map.VerifyKeyHasMetaInfo(assertCond, pass);

        map.VerifyNoDuplicateKeys(assertCond, pass);

        if (expectedKeys != null)
            map.VerifyContainAllKeys(expectedKeys, assertCond, pass);
    }

    /// <summary>Verifies that the hashes correspond to the keys stored in the entries. May be called tests.</summary>
    public static void VerifyHashesAndKeysEq<TMap, K>(ref this TMap map, Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMap<K>, IMapImpl<K>
    {
        var metas = map.PackedEntryIndexesHashesProbes;
        var probeMask = map.Capacity - 1;
        for (var i = 0; i < metas.Length; i++)
        {
            var m = metas[i];
            if (m != 0)
            {
                var metaHashPart = (int)(m & ~probeMask);
                var entryIndex = (int)(m >>> EntryIndexStartAtBit);

                var key = map.GetSurePresentKey(entryIndex);
                var keyHash = map.GetHashCode(key);
                var keyHashPart = keyHash & ~probeMask;
                assertCond(metaHashPart == keyHashPart, $"Hash mismatch for i:{i}, entryIndex:{entryIndex}, key:{key}, expected:{keyHashPart}, actual:{metaHashPart}");
            }
        }
    }

    /// <summary>Verifies that there is no duplicate keys stored in hashes -> entries. May be called from the tests.</summary>
    public static void VerifyNoDuplicateKeys<TMap, K>(this TMap map, Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMap<K>, IMapImpl<K>
    {
        var uniq = new Dictionary<K, int>(map.Count);

        var metas = map.PackedEntryIndexesHashesProbes;
        var probeMask = map.Capacity - 1;
        for (var i = 0; i < metas.Length; i++)
        {
            var m = metas[i];
            if (m == 0)
                continue;

            var entryIndex = (int)(m >>> EntryIndexStartAtBit);
            var key = map.GetSurePresentKey(entryIndex);

            if (!uniq.ContainsKey(key))
                uniq.Add(key, 1);
            else
                assertCond(false, $"Duplicate key: {key}");
        }
    }

    /// <summary>Verifies that the probes are consistently increasing</summary>
    public static void VerifyProbesRobinHoodInvariants<TMap, K>(this TMap map, Action<bool, string> assertCond, Pass<K> _ = default,
        int startIndex = 0, int endIndex = -1)
        where TMap : struct, IMapImpl<K>
    {
        var metas = map.PackedEntryIndexesHashesProbes;
        var probeMask = map.Capacity - 1;
        var prevProbe = (startIndex == 0 ? metas[metas.Length - 1] : metas[startIndex - 1]) & probeMask;

        endIndex = endIndex == -1 ? metas.Length : endIndex;
        for (var i = startIndex; i < endIndex; i++)
        {
            var probe = metas[i] & probeMask;
            var invariant = prevProbe >= probe || prevProbe + 1 == probe;
            assertCond(invariant, $"Probe invariant failed for probe index {i}, probe:{probe}, prevProbe:{prevProbe}");
            prevProbe = probe;
        }
    }

    /// <summary>Verifies that each key has a corresponding hash entry which is correctly references this key</summary>
    public static void VerifyKeyHasMetaInfo<TMap, K>(ref this TMap map,
        Action<bool, string> assertCond, Pass<K> _ = default)
        where TMap : struct, IMap<K>
    {
        for (var i = 0; i < map.Count; ++i)
        {
            var key = map.GetSurePresentKey(i);
            var foundIndex = map.TryGetIndex(key);
            assertCond(foundIndex != -1, $"Not found (foundIndex:-1) for entryIndex:{i}, key:{key}");
            assertCond(foundIndex == i, $"Does not correspond foundIndex:{foundIndex}, i:{i}, key:{key}");
        }
    }

    /// <summary>Verifies that the map contains all passed keys. May be called from the tests.</summary>
    public static void VerifyContainAllKeys<TMap, K>(ref this TMap map,
        IEnumerable<K> expectedKeys, Action<bool, string> assertContains, Pass<K> _ = default)
        where TMap : struct, IMap<K>
    {
        foreach (var key in expectedKeys)
            assertContains(map.ContainsKey(key), $"Key not found: {key}");
    }
}

public interface IMap<K>
{
    /// <summary>Number of entries in the map</summary>
    int Count { get; }
    /// <summary>Lookups for the stored key. Returns its index in the entries or -1</summary>
    int TryGetIndex(K key);
    /// <summary>Lookups for the stored key. If found true, otherwise false</summary>
    bool ContainsKey(K key);
    /// <summary>Lookups for the stored key by the index in the entries data structure</summary>
    K GetSurePresentKey(int entryIndex);
}

public interface IMap<K, TEntry> : IMap<K>
    where TEntry : struct, IEntry<K>
{
    /// <summary>Returns the ref to the found entry or the null ref</summary>
    [UnscopedRef]
    ref TEntry TryGetEntryRef(K key, out bool found);

    /// <summary>Returns the ref to the found entry or Adds the entry if not found</summary>
    [UnscopedRef]
    ref TEntry AddOrGetEntryRef(K key, out bool found);

    /// <summary>Adds an entry for sure absent key. Provides the performance in scenarios where you know the key is not yet in the map</summary>
    [UnscopedRef]
    ref TEntry AddSureAbsentDefaultEntryAndGetRef(K key);
}

/// <summary>Implementation details</summary>
public interface IMapImpl<K>
{
    /// <summary>The Capacity</summary>
    int Capacity { get; }
    /// <summary>The metadata</summary>
    long[] PackedEntryIndexesHashesProbes { get; }
    /// <summary>Returns the hash code for the provided key using the IEq implementation used by this map</summary>
    int GetHashCode(K key);
}

#if DEBUG
/// <summary>Represents unpacked metadata for debugging - matches long layout</summary>
[DebuggerDisplay("{ToString(),nq}")]
[StructLayout(LayoutKind.Explicit, Size = 8)]
public readonly struct DebugMetaUnpacked
{
    [FieldOffset(0)]
    public readonly uint HashAndProbe;

    [FieldOffset(4)]
    public readonly uint EntryIndex;

    public override string ToString() =>
        HashAndProbe == 0 ? "empty" : $"ei:{EntryIndex}, hp:0b{Convert.ToString(HashAndProbe, 2).PadLeft(32, '0')}";
}
#endif

/// <summary>
/// Fast and less-allocating hash map without thread safety nets. Please measure it in your own use case before use.
/// It is configurable in regard of hash calculation/equality via `TEq` type parameter and 
/// in regard of key-value storage via `TEntries` type parameter.
/// 
/// Details:
/// - Implemented as a struct so that the empty/default map does not allocate on heap
/// - Hashes and key-values are the separate collections enabling better cash locality and faster performance (data-oriented design)
/// - No SIMD for now to avoid complexity and costs for the smaller maps, so the map is more fit for the smaller sizes.
/// - Provides the "stable" enumeration of the entries in the added order
/// - The TryRemove method removes the hash but replaces the key-value entry with the tombstone key and the default value.
/// For instance, for the `RefEq` the tombstone is <see langword="null"/>. You may redefine it in the `IEq{K}.GetTombstone()` implementation.
/// 
/// </summary>
[DebuggerDisplay("Count = {Count}, Capacity = {Capacity}")]
public struct SmallMap<K, TEntry, TEq, TStackCap, TStackHashes, TStackEntries, THeapEntries> : IMap<K, TEntry>, IMapImpl<K>
    where TEntry : struct, IEntry<K>
    where TEq : struct, IEq<K>
    where TStackCap : struct, ISize2Plus
    where TStackHashes : struct, IStack<int, TStackCap, TStackHashes>
    where TStackEntries : struct, IStack<TEntry, TStackCap, TStackEntries>
    where THeapEntries : struct, IEntries<K, TEntry>
{
#if DEBUG
    // Diagnostic counters to measure the performance of the map operations
    public int PutMetadataWithoutResizing_Count = 0;
    public int PutHashAndIndexWithoutResizing_ProbeGreaterOrEqualCheckCount = 0;
    public int AddOrGetRefInEntries_Count = 0;
    public int ResizeProbesAndHashes_Count = 0;
#endif

    internal int _capacityPowerOfTwo;
    internal int _count;

    // Packing hash and probe together enables single load to examine probe and hash 
    // and enables the fast check even without the unpacking both values.
    // Packing entry index in the high bits saves on the array load and possible cache eviction plus simplifies the resize, because the index part can be copied as-is
    // If the whole long is 0 then the slot is free.
    // 0..01|00010000...110|00010
    //     |    |             |- The probe, occupies indexMask of bits always starting with 1, so the occupied item should have non 0 value
    //     |    |- The remaining part of the hash without the indexMask bits used for the item index.
    //     |- The entry index stored in the high bits
    internal long[] _packedEntryIndexesHashesProbes;

#if DEBUG && SUPPORTS_UNSAFE
    public Span<DebugMetaUnpacked> DebugMetaUnpacked
    {
        get
        {
            var packed = _packedEntryIndexesHashesProbes;
            if (packed == null || packed.Length == 0)
                return Span<DebugMetaUnpacked>.Empty;
            return MemoryMarshal.Cast<long, DebugMetaUnpacked>(packed.AsSpan());
        }
    }
#endif

#pragma warning disable IDE0044 // it tries to make entries readonly but they should stay modify-able to prevent its defensive struct copying
#pragma warning disable CS0649 // field is never assigned to, and will always have its default value
    internal TStackHashes _stackHashes;
    internal TStackEntries _stackEntries;
    internal THeapEntries _heapEntries;
#pragma warning restore CS0649
#pragma warning restore IDE0044

    /// <summary>Capacity</summary>
    public int Capacity => _capacityPowerOfTwo;

    /// <summary>Access to the entry indexes, hashes and corresponding probes</summary>
    public long[] PackedEntryIndexesHashesProbes => _packedEntryIndexesHashesProbes;

    /// <inheritdoc />
    public int Count => _count;

    /// <summary>Access to the key-value entries</summary>
    public THeapEntries HeapEntries => _heapEntries;

    /// <summary>Capacity calculates as `1 leftShift capacityBitShift`</summary>
    public SmallMap(uint capacityPowerOfTwoPlease)
    {
        var capacityPowerOfTwo = capacityPowerOfTwoPlease < MinCapacity
            ? MinCapacity
            : GetNextPowerOfTwoFast(capacityPowerOfTwoPlease);

        _capacityPowerOfTwo = (int)capacityPowerOfTwo;
        _packedEntryIndexesHashesProbes = new long[capacityPowerOfTwo];
        _heapEntries.Init(capacityPowerOfTwo);
    }

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int GetHashCode(K key) => default(TEq).GetHashCode(key);

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public K GetSurePresentKey(int entryIndex)
    {
        Debug.Assert(entryIndex >= 0 & entryIndex < _count, $"Entry index {entryIndex} should be in the range 0..{_count - 1}");
        return (entryIndex >= _stackEntries.Capacity
            ? _heapEntries.GetSurePresentRef(entryIndex - _stackEntries.Capacity)
            : _stackEntries.GetSurePresentItemRef(entryIndex))
            .Key;
    }

    // todo: @perf make it an interface method to store the actual entry in place of the 32 bit index, e.g. store and actual int key for the int Set
    ///<summary>Get the value ref by the entry index. Also the index corresponds to entry adding order.
    /// Important: it does not check the index bounds, so you need to check that the index is from 0 to map.Count-1</summary>
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry GetSurePresentEntryRef(int entryIndex)
    {
        Debug.Assert(entryIndex >= 0 && entryIndex < _count, $"Index {entryIndex} should be in the range 0..{_count - 1}");
        if (entryIndex >= _stackEntries.Capacity)
            return ref _heapEntries.GetSurePresentRef(entryIndex - _stackEntries.Capacity);
        return ref _stackEntries.GetSurePresentItemRef(entryIndex);
    }

    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    private ref TEntry AddOrGetRefInEntries(K key, int hash, out bool found)
    {
#if DEBUG
        ++AddOrGetRefInEntries_Count;
#endif
#if NET7_0_OR_GREATER
        ref var metas = ref MemoryMarshal.GetArrayDataReference(_packedEntryIndexesHashesProbes);
#else
        ref var metas = ref _packedEntryIndexesHashesProbes;
#endif
        found = true;
        var probeMask = _capacityPowerOfTwo - 1;
        var meta = (long)_count << EntryIndexStartAtBit | (long)(hash & ~probeMask) | 1L;
        var metaIndex = hash & probeMask;
        while (true)
        {
            ref var mRef = ref metas.GetSurePresentItemRef(metaIndex & probeMask);
            if ((mRef & probeMask) < (meta & probeMask))
            {
                var mRobinHooded = mRef;
                mRef = meta;
                if (mRobinHooded == 0) // finish on the empty slot
                    break;
                meta = mRobinHooded;
            }

            if ((mRef & HashAndProbeMask) == (meta & HashAndProbeMask))
            {
                var entryIndex = (int)(mRef >>> EntryIndexStartAtBit);
                ref var eRef = ref GetSurePresentEntryRef(entryIndex);
                if (default(TEq).Equals(eRef.Key, key))
                    return ref eRef;
            }

            ++meta;
            ++metaIndex;
        }

        found = false;
        ref var newEntry = ref _heapEntries.AddDefaultAndGetRef();
        newEntry.Key = key;
        ++_count;

        // The new metadata slot is added - this is a good place to resize the metadata.
        // If the free space is less than ~1/8 of capacity (~12.5%).
        if (_capacityPowerOfTwo - _count <= (_capacityPowerOfTwo >>> MinFreeCapacityShift))
            ResizeMetadata();

        return ref newEntry;
    }

    [MethodImpl((MethodImplOptions)256)]
    private void PutMetadataWithoutResizing(int probeMask, int hash, int entryIndex)
    {
#if DEBUG
        ++PutMetadataWithoutResizing_Count;
#endif
#if NET7_0_OR_GREATER
        ref var metas = ref MemoryMarshal.GetArrayDataReference(_packedEntryIndexesHashesProbes);
#else
        var metas = _packedHashesAndProbes;
#endif

        var meta = (long)entryIndex << EntryIndexStartAtBit | (long)(hash & ~probeMask) | 1L;
        var metaIndex = hash & probeMask;
        while (true)
        {
            ref var mRef = ref metas.GetSurePresentItemRef(metaIndex & probeMask);
            if ((mRef & probeMask) < (meta & probeMask))
            {
                var mRobinHooded = mRef;
                mRef = meta;
                if (mRobinHooded == 0) // finish on the empty slot
                    return;
                meta = mRobinHooded;
            }

            ++metaIndex;
            ++meta;
        }
    }

    /// <inheritdoc />
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry AddOrGetEntryRef(K key, out bool found)
    {
        var hash = default(TEq).GetHashCode(key);

        if (_count > _stackEntries.Capacity)
            return ref AddOrGetRefInEntries(key, hash, out found);

        var i = _stackEntries.TryGetStackEntryIndex(ref _stackHashes, _count, key, hash, Pass<TEq, TStackCap, TEntry>.It);
        if (found = i != -1)
            return ref _stackEntries.GetSurePresentItemRef(i);

        // Add the new entry to the stack if there is still space in the stack
        if (_count < _stackEntries.Capacity)
        {
            var addedIndex = _count++;
            _stackHashes.GetSurePresentItemRef(addedIndex) = hash;
            ref var newStackEntry = ref _stackEntries.GetSurePresentItemRef(addedIndex);
            newStackEntry.Key = key;
            return ref newStackEntry;
        }

        return ref MigrateToHeapAndAddEntry(key, hash);
    }

    private ref TEntry MigrateToHeapAndAddEntry(K key, int hash)
    {
        // Now all capacity of the stack is used.
        // To avoid double work always going linearly through the Stack with the comparison,
        // let's calculate the hash of the keys stored on stack and put them 
        // to the usual HashMap packed hashes and indexes array for the promised O(1) lookup.
        // But the key-value entries will remain on the Stack, and for the found index of the entry we use the GetSurePresentItemRef(index)
        // to get the entry reference either from the Stack or the TEntries.
        // So the entries on stack are guarantied to be stable from the beginning of the map creation, 
        // because they are not copied when the Entries need to Resize (depending on the TEntries implementation). 
        // To ensure stable entries on Entries you need to use 

        var stackCapacity = _stackEntries.Capacity;
        var newCapacity = Math.Max(_capacityPowerOfTwo, stackCapacity << 1);
        _capacityPowerOfTwo = newCapacity;
        _packedEntryIndexesHashesProbes = new long[newCapacity];

        var probeMask = newCapacity - 1;
        for (var i = 0; i < stackCapacity; ++i)
        {
            var h = _stackHashes.GetSurePresentItemRef(i);
            PutMetadataWithoutResizing(probeMask, h, i);
        }

        PutMetadataWithoutResizing(probeMask, hash, stackCapacity);

        ++_count;

        // Creating the heap entries in addition to the stack entries, so the stack entries remain stable and never migrate
        _heapEntries.Init((uint)stackCapacity);

        // Set the key for the first entry, which is the 0 index in the entries
        ref var newEntry = ref _heapEntries.AddDefaultAndGetRef();
        newEntry.Key = key;
        return ref newEntry;
    }

    /*
    Insertion step by step:

    1. Initially the map is empty. Its capacity mask is 7:
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [0]  [0]  [0]

    2. Insert the key A with the hash 13, which is 0b0011_0101. 13 & 7 Mask = 5, so the index is 5.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [13] [0]  [0]
    Probe:                           1A

    3. Insert the key B with the hash 5, which is 0b0000_1011. 5 & 7 Mask = 5, so the index is again 5.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [13] [5]  [0]
    Probe                            1A   2B

    4. Insert the key C with the hash 7, which is 0b0010_0101. 7 & 7 Mask = 7, so the index is 7.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [0]  [0]  [0]  [0]  [0]  [13] [5]  [7]
    Probe:                           1A   2B   1C

    5. Insert the key D with the hash 21, which is 0b0101_0101. 21 & 7 Mask = 5, so the index is again again 5.
    Index:  0    1    2    3    4    5    6    7
    Hash:  [7]  [0]  [0]  [0]  [0]  [13] [5]  [21]
    Probe:  2C                       1A   2B   3D
    */
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    private ref TEntry AddSureAbsentDefaultAndGetRefInEntries(K key, int hash)
    {
        if (_capacityPowerOfTwo - _count <= (_capacityPowerOfTwo >>> MinFreeCapacityShift))
            ResizeMetadata();

        PutMetadataWithoutResizing(_capacityPowerOfTwo - 1, hash, _count);

        ++_count;
        ref var entry = ref _heapEntries.AddDefaultAndGetRef();
        entry.Key = key;
        return ref entry;
    }

    /// <inheritdoc />
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry AddSureAbsentDefaultEntryAndGetRef(K key)
    {
        var hash = default(TEq).GetHashCode(key);

        if (_count > _stackEntries.Capacity)
            return ref AddSureAbsentDefaultAndGetRefInEntries(key, hash);

        // Add the new entry to the stack if there is still space in stack
        if (_count < _stackEntries.Capacity)
        {
            var newIndex = _count++;
            _stackHashes.GetSurePresentItemRef(newIndex) = hash;
            ref var newStackEntry = ref _stackEntries.GetSurePresentItemRef(newIndex);
            newStackEntry.Key = key;
            return ref newStackEntry;
        }

        return ref MigrateToHeapAndAddEntry(key, hash);
    }

    /// <inheritdoc />
    [MethodImpl((MethodImplOptions)256)]
    public int TryGetIndex(K key)
    {
        var hash = default(TEq).GetHashCode(key);
        return _count > _stackEntries.Capacity
            ? TryGetIndexInEntries(key, hash)
            : _stackEntries.TryGetStackEntryIndex(ref _stackHashes, _count, key, hash, Pass<TEq, TStackCap, TEntry>.It);
    }

    /// <inheritdoc />
    public bool ContainsKey(K key) => TryGetIndex(key) != -1;

    [MethodImpl((MethodImplOptions)256)]
    internal int TryGetIndexInEntries(K key, int hash)
    {
#if NET7_0_OR_GREATER
        ref var metas = ref MemoryMarshal.GetArrayDataReference(_packedEntryIndexesHashesProbes);
#else
        var metas = _packedHashesAndProbes;
#endif
        var probeMask = _capacityPowerOfTwo - 1;
        var meta = (long)(hash & ~probeMask) | 1L;
        var metaIndex = hash & probeMask;
        while (true)
        {
            ref var mRef = ref metas.GetSurePresentItemRef(metaIndex & probeMask);
            if ((mRef & probeMask) < (meta & probeMask))
                return -1;

            if ((mRef & HashAndProbeMask) == meta)
            {
                var entryIndex = (int)(mRef >>> EntryIndexStartAtBit);
                ref var entry = ref GetSurePresentEntryRef(entryIndex);
                if (default(TEq).Equals(entry.Key, key))
                    return entryIndex;
            }

            ++meta;
            ++metaIndex;
        }
    }

    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    internal ref TEntry TryGetEntryRef(K key, int hash, out bool found)
    {
        found = false;
#if NET7_0_OR_GREATER
        ref var metas = ref MemoryMarshal.GetArrayDataReference(_packedEntryIndexesHashesProbes);
#else
        var metas = _packedHashesAndProbes;
#endif
        var probeMask = _capacityPowerOfTwo - 1;
        var meta = (long)(hash & ~probeMask) | 1L;
        var metaIndex = hash & probeMask;
        while (true)
        {
            ref var mRef = ref metas.GetSurePresentItemRef(metaIndex & probeMask);
            if ((mRef & probeMask) < (meta & probeMask))
                return ref RefTools<TEntry>.GetNullRef();

            if ((mRef & HashAndProbeMask) == meta)
            {
                var entryIndex = (int)(mRef >>> EntryIndexStartAtBit);
                ref var entry = ref GetSurePresentEntryRef(entryIndex);
                if (default(TEq).Equals(entry.Key, key))
                {
                    found = true;
                    return ref entry;
                }
            }

            ++meta;
            ++metaIndex;
        }
    }

    /// <inheritdoc />
    [UnscopedRef]
    [MethodImpl((MethodImplOptions)256)]
    public ref TEntry TryGetEntryRef(K key, out bool found)
    {
        var hash = default(TEq).GetHashCode(key);
        if (_count > _stackEntries.Capacity)
            return ref TryGetEntryRef(key, hash, out found);

        var i = _stackEntries.TryGetStackEntryIndex(ref _stackHashes, _count, key, hash, Pass<TEq, TStackCap, TEntry>.It);
        if (found = i != -1)
            return ref _stackEntries.GetSurePresentItemRef(i);

        return ref RefTools<TEntry>.GetNullRef();
    }

    internal void ResizeMetadata()
    {
#if DEBUG
        ++ResizeProbesAndHashes_Count;
#endif
        var oldCapacity = _capacityPowerOfTwo;
        var newCapacity = _capacityPowerOfTwo << 1;

        var newMetasArr = new long[newCapacity];

#if NET7_0_OR_GREATER
        ref var newMetas = ref MemoryMarshal.GetArrayDataReference(newMetasArr);
        ref var metas = ref MemoryMarshal.GetArrayDataReference(_packedEntryIndexesHashesProbes);
#else
        var newMetas = newMetasArr;
        var metas = _packedEntryIndexesHashesProbes;
#endif
        var probeMask = oldCapacity - 1;
        var newProbeMask = newCapacity - 1;

        for (var metaIndex = 0; metaIndex < oldCapacity; ++metaIndex)
        {
            var m = metas.GetSurePresentItem(metaIndex);
            if (m != 0)
            {
                // Сalculate the ideal hash index for the current probe
                var p = (int)(m & probeMask);
                // Add oldCapacity then clamp with probeMask to avoid negative values for the wrapped-around indexes
                var idealIndex = (oldCapacity + metaIndex - p + 1) & probeMask;
                Debug.Assert(idealIndex >= 0, $"Ideal index should be non-negative, but found {idealIndex}");

                // Calculate the new ideal index based on the next bit after the index mask (an oldCapacity bit).
                // If the bit is 0 then the new index is the same otherwise it is oldCapacity + idealIndex, or in other words...
                var newMeta = (m & ~newProbeMask) | 1L; // starting probe is always 1
                var newMetaIndex = (int)(m & oldCapacity) | idealIndex;

                // Using robin-hood resordering, even if it is required only for the wrapped-around cases.
                // But this is fine because after resize it will be less frequent and comparing to just insertion it is just one check more.
                while (true)
                {
                    ref var newMetaRef = ref newMetas.GetSurePresentItemRef(newMetaIndex & newProbeMask);
                    if ((newMetaRef & newProbeMask) < (newMeta & newProbeMask))
                    {
                        var mRobinHooded = newMetaRef;
                        newMetaRef = newMeta;
                        if (mRobinHooded == 0) // finish on the empty slot
                            break;
                        newMeta = mRobinHooded;
                    }

                    ++newMeta; // actually incrementing the probe, it is save because probe has the space of the whole capacity constrained by the probeMask
                    ++newMetaIndex;
                }
            }
        }

        _capacityPowerOfTwo = newCapacity;
        _packedEntryIndexesHashesProbes = newMetasArr;

#if VERIFY_MAP
        this.VerifyKeyHasMetaInfo(static (x, msg) => Debug.Assert(x, msg), Pass<K>.It);
#endif
    }
}

/// <summary>Holds the Map with 4 items on stack. Minimizes the number of type arguments required to be specified</summary>
public struct SmallMap4<K, V, TEq>() where TEq : struct, IEq<K>
{
    /// <summary>Map with 4 elements on stack and entries baked by the single array</summary> 
    public SmallMap<K, SmallMap.Entry<K, V>, TEq, Size4, Stack4<int>, Stack4<SmallMap.Entry<K, V>>,
        SmallMap.StableArrayEntries<K, SmallMap.Entry<K, V>>> Map;
    public SmallMap4(byte capacityBitShift) : this() => Map = new(capacityBitShift);
}

